        const validator = common$1.ProgramBuilder.create("common$GraphSettingValidatorAttrProgram" /* EN_PROGRAM_ID.GraphSettingValidatorAttrProgram */, this.execution_context);
        const is_valid = await validator.executeAsync({
            vmc,
            current_template_info: current_template_info?.code,
            is_za_template: current_template_info?.is_za_template,
            screen_type: current_template_info?.screen_type,
            template_sub_type: dto.template_sub_type,
            menu_type: this.execution_context.getProgramContext().data.menu_type,
            axis_info: cloned_data_view_format?.setting?.axisInfo,
