function setChartOption({ chartOption, platform_config, }) {
    switch (platform_config.graphType) {
        case 'area':
        case 'line':
            chartOption.lineConfig = { groupConfig: {} };
            chartOption.scatterConfig = { groupConfig: {} };
            // 라인 정보 설정
            _.first(chartOption.datas)?.values.forEach((data) => {
                chartOption.lineConfig.groupConfig[data.groupId] = {
                    visible: true,
                    strokeWidth: 1,
                    strokeOpacity: 1,
                };
                chartOption.scatterConfig.groupConfig[data.groupId] = {
                    visible: true,
                    strokeWidth: 1,
                    strokeOpacity: 1,
                };
            });
            break;
    }
}

