         * 1. 표영역분리 설정을 사용으로 설정한 경우<br>
         * 2. 페이지조회방법을 한 페이지씩으로 설정한 경우<br>
         * 3. 반복설정을 적용한 경우<br>
         * 4. 문자형 또는 숫자형 항목이 없는 경우
         * 5. 비교기간을 선택한 경우
         */
        // 반복 설정이 되어 있는 경우
        if (validate_check.repeat_tf == true) {
            return false;
        }
        // 고정형반복설정 항목이 있는 경우
        if (validate_check.fixed_pivot_tf == true) {
            return false;
        }
        // 표영역 분리 사용인 경우
        if (validate_check.item_separate_tf == true) {
            return false;
        }
        // 한페이씩 설정인 경우
        if (validate_check.page_option.page_lookup_type == "T" /* EN_TEMPLATE_PAGE_LOOKUP_TYPE.Current */) {
            return false;
        }
        //비교기간을 선택한 경우
        if (aggregate_comparison_period !== "0" /* EN_COMPARISON_PERIOD.None */) {
            return false;
        }
        // 문자형 또는 숫자형 항목이 없는 경우
        if (_.vIsEmpty(dto.axis_info?.xaxis) || _.vIsEmpty(dto.axis_info?.yaxis)) {
            return false;
        }
        return true;
    }

declareProgramContext(dto) {
        const program_context = this.execution_context.getProgramContext();
        return {
            data_type: 'GetTemplateItemDefinitionProgram',
            data: program_context.data,
        };
    }

async onExecuteAsync(request) {
        const program_context = this.execution_context.getProgramContext();
        //search
        const search_attribute = program_context.sourceData.menu_attr?.search?.data;
        const search_data_model_id = search_attribute?.data_model_id.search;
        const search_dmc = program_context.data.dmc_map[search_data_model_id];
        //집계
        const aggregate_prop_id = search_dmc.getPropIdByReferType('aggregate');
        const aggregate_type = search_dmc.getValueByPropId(aggregate_prop_id)?.aggregate_key?.type ?? "fixed" /* EN_TEMPLATE_SUB_TYPE.Fixed */;
        // 현황 ID
        const menu_type = _.vSafe(program_context.data.menu_type);
        const data_model_id = program_context.sourceData.menu?.definition?.model_info_list.find((x) => x.model_refer_type === menu_type)?.model_id;
        //기본값
        const axis_info = { xaxis: [], yaxis: [] };
        //서버-액션을 통해 prop_id를 불러오기
        const racCommand = common.RacCommandBuilder.createCommon("/ec56/api/app.setup/action/template/GetPropDisplayNameAction" /* EN_ACTION_ID.IGetPropDisplayNameAction */, this.execution_context);
        const request_menu_type = getTemporaryMenuTypeForSumStatus(menu_type);
        const api_result = await racCommand.executeAsync({
            bizz_sid: program_context.data.bizz_sid,
            menu_sid: program_context.data.menu_sid,
            menu_type: request_menu_type,
            template_set_sid: request.current_template_info,
            template_sub_type: aggregate_type,
            za_tf: request.is_za_template,
            data_model_id: getTemporaryDataModelIdForSumStatus(data_model_id),
            screen_type: request.screen_type,
        });
        //////////////////////////////////////////////////
        //axias_info 정리하기
        //////////////////////////////////////////////////
        //data_type이 numeric이지만, yaxis에 들어가야 하는 값들
        //TODO: 수정예정
        const yaxis_list = ['cust$cust$cust_limit_term', 'prod$prod$deno_rate'];
        if (aggregate_type === "free" /* EN_TEMPLATE_SUB_TYPE.Free */) {
            // 집계인 경우
            //가로축 : 집계조건
            //세로축 : 설정해둔 항목 중 숫자형 항목 (데이터타입)
            const condition_list = search_dmc.getValueByPropId(aggregate_prop_id);
            axis_info.xaxis.push(..._.keys(condition_list)
                .filter((x) => x.startsWith('condition') && !_.isNil(condition_list[x]?.prop_id))
                .map((x) => {
                return {
                    id: condition_list[x].prop_id,
                    title: condition_list[x].prop_name,
                };
            }));
            //집계조건이 없는 경우 예외처리
            if (aggregate_type === "free" /* EN_TEMPLATE_SUB_TYPE.Free */ && axis_info.xaxis.length === 0) {
                await request.vmc.alertAsync($Resx.rex00371);
                return {};
            }
            api_result.forEach((prop) => {
                if (prop.prop_data_type === "$$decimal" /* EN_DATA_TYPE_ID_OLD.$$decimal */) {
                    axis_info.yaxis.push({ id: prop.prop_id, title: prop.prop_name });
                }
            });
        }
        else {
            // 내역인 경우
            //가로축 : 설정해둔 항목 중 decimal 항목이 아닌 것 (데이터타입)
            //세로축 : 설정해둔 항목 중 decimal 항목 (데이터타입)
            api_result.forEach((prop) => {
                const target_axis = prop.prop_data_type === "$$decimal" /* EN_DATA_TYPE_ID_OLD.$$decimal */ || yaxis_list.includes(prop.prop_id)
                    ? axis_info.yaxis
                    : axis_info.xaxis;
                target_axis.push({ id: prop.prop_id, title: prop.prop_name });
            });
        }
        // 이미지 제외
        axis_info.xaxis = axis_info.xaxis.filter((item) => item.id != 'prod$prod$prod_img');
        return { axis_info };
    }

shouldExecute() {
        const template_id = this._getTemplateModelId();
        if (!template_id)
            return false;
        return this._isGraph(template_id);
    }

async executeAsync({ section_data_modifiers }) {
        const grid_model_id = this._getGridModelId();
        const template_id = this._getTemplateModelId();
        if (!grid_model_id || !template_id)
            return;
        const modifier = section_data_modifiers[grid_model_id];
        if (!modifier)
            return;
        const data_view_format = this._getDataViewFormat(template_id);
        const graph_config = data_view_format?.setting;
        const view_type = this._getChartViewType(graph_config?.graphType);
        // chart 위젯에 graph_config / view_type attr 주입
        modifier.addAttribute({
            prop_id: '',
            attr_type: "Renderer" /* EN_ATTR_TYPE.Renderer */,
            attr_id: 'graph_config',
            data: graph_config,
        });
        modifier.addAttribute({
            prop_id: '',
            attr_type: "Renderer" /* EN_ATTR_TYPE.Renderer */,
            attr_id: 'view_type',
            data: view_type,
        });
        modifier.execute();
    }

_getGridModelId() {
        const program_context = this.execution_context.getProgramContext();
        const menu_type = program_context.data.menu_type;
        return program_context.sourceData.menu?.definition?.model_info_list.find((x) => x.model_refer_type === menu_type)?.model_id;
    }

_getTemplateModelId() {
        const program_context = this.execution_context.getProgramContext();
        const search = program_context.sourceData.menu_attr?.search?.data;
        return search?.data_model_id?.template;
    }

_getChartViewType(graph_type) {
        switch (graph_type) {
            case "horizontalBar" /* EN_GRAPH_TYPE.horizontalBar */:
                return "HORIZONTALBAR_CHART" /* EN_VIEW_TYPE.HorizontalbarChart */;
            case "line" /* EN_GRAPH_TYPE.line */:
                return "LINE_CHART" /* EN_VIEW_TYPE.LineChart */;
            case "pie" /* EN_GRAPH_TYPE.pie */:
                return "PIE_CHART" /* EN_VIEW_TYPE.PieChart */;
            case "area" /* EN_GRAPH_TYPE.area */:
                return "AREA_CHART" /* EN_VIEW_TYPE.AreaChart */;
            case "bar" /* EN_GRAPH_TYPE.bar */:
            default:
                return "VERTICALBAR_CHART" /* EN_VIEW_TYPE.VerticalbarChart */;
        }
    }

function sortResult(result,fields,order){
  if(order.length){const indexes=new Map(fields.map((f,i)=>[f.id,i])),decorated=result.rows.map((row,index)=>({row,index}));decorated.sort((a,b)=>{for(const rule of order){const i=indexes.get(rule.field),left=a.row[i],right=b.row[i],emptyA=left==null||left==='',emptyB=right==null||right==='';let value=emptyA||emptyB?(emptyA===emptyB?0:emptyA?-1:1):fields[i].kind==='number'?Number(left)-Number(right):String(left).localeCompare(String(right),'ko',{numeric:true});if(value)return rule.direction==='desc'?-value:value;}return a.index-b.index;});result.rows=decorated.map(x=>x.row);if(result.rowRecords)result.rowRecords=decorated.map(x=>result.rowRecords[x.index]);if(result.records)result.records=decorated.map(x=>result.records[x.index]);}
  result.sort=order;result.sortFields=fields;result.sortLabel=order.map(r=>(fields.find(f=>f.id===r.field)?.label||r.field)+' '+(r.direction==='desc'?'내림차순':'오름차순')).join(' / ');return result;
 }

function search(db,type,filter={}){
  const spec=specifications[type];if(!spec)throw Error('직접 관찰되지 않은 현황 화면입니다.');
  validateDates(filter);
  const mode=filter.mode||'detail';if(!['detail','summary'].includes(mode))throw Error('조회 메뉴를 확인하세요.');
  if(mode==='summary'&&type!=='purchase')throw Error('이 화면의 집계 결과는 아직 확인하지 않았습니다.');
  let axes=[],axisDirections=[];if(mode==='summary'){
   if(!Array.isArray(filter.axes)||filter.axes.some(x=>typeof x!=='string'))throw Error('집계조건은 1개 이상 선택해야 합니다.');
   if(filter.axes.length>5)throw Error('집계조건은 최대 5개입니다.');
   const directions=filter.axisDirections===undefined?[]:filter.axisDirections;if(!Array.isArray(directions)||directions.length&&directions.length!==filter.axes.length||directions.some(x=>!['asc','desc'].includes(x)))throw Error('집계 방향을 확인하세요.');
   axisDirections=filter.axes.flatMap((axis,i)=>axis?[directions[i]||'asc']:[]);
   axes=filter.axes.filter(Boolean);if(!axes.length)throw Error('집계조건은 1개 이상 선택해야 합니다.');
   if(axes.some(x=>!summaryAxes.includes(x)))throw Error('지원하는 집계조건을 선택하세요.');
   if(new Set(axes).size!==axes.length)throw Error('집계조건을 중복 선택할 수 없습니다.');
  }
  if(mode==='detail'&&filter.grouping&&filter.grouping!=='라인별')throw Error('이 구분의 결과 화면은 아직 확인하지 않았습니다.');
  const fields=sortFields(type,{mode,axes}),order=validateSort(type,filter,fields);
  if(filter.tradeType||filter.serialLot)throw Error('해당 검색 조건의 원본 하위 규칙은 아직 확인하지 않았습니다.');
  if(filter.managedItem)throw Error('관리항목 조회 규칙은 아직 확인하지 않았습니다.');
  if(filter.comparison&&filter.comparison!=='사용안함')throw Error('기간 비교 결과는 아직 확인하지 않았습니다.');
  const query=String(filter.query||'').trim().toLowerCase(),groups=[];
  for(const doc of db.documents){
   if(doc.type!==type||!C.listed(doc)||!within(doc.date,filter.from,filter.to)||filter.number&&!doc.id.includes(filter.number)||filter.warehouse&&doc.warehouse!==filter.warehouse||filter.project&&doc.project!==filter.project)continue;
   const foreign=Boolean(doc.currency&&doc.currency!=='KRW');if(filter.currency==='domestic'&&foreign||filter.currency==='foreign'&&!foreign)continue;
   const lines=doc.lines.filter(line=>within(line.dueDate||doc.dueDate,filter.dueFrom,filter.dueTo)&&(!filter.partner||(line.supplier||doc.partner)===filter.partner)&&(!filter.item||line.item===filter.item));
   if(!lines.length)continue;
   const lineState=line=>C.purchasingLineState?C.purchasingLineState(doc,line).progress:line.progress??(C.purchasingState?C.purchasingState(doc).progress:doc.status);
   const state=doc.lines.every(l=>lineState(l)==='완료')?'완료':'진행중';
   const headerValues={id:doc.date+' '+doc.id,partner:lookup(db,'partners',doc.partner),employee:lookup(db,'employees',doc.employee),warehouse:lookup(db,'warehouses',doc.warehouse),dueDate:doc.dueDate||'',reference:doc.reference||'',progress:state};
   const header=spec.headerKeys.map(key=>headerValues[key]??'');
   const details=lines.map(line=>{const item=C.master(db,'items',line.item),amount=C.effectiveLineTotals(doc,line),name=(item?.name||line.item)+(item?.spec?(type==='request'?' ('+item.spec+')':' ['+item.spec+']'):'');const order=doc.sourceId?db.documents.find(d=>d.id===doc.sourceId&&d.type==='purchaseorder'):null;const fields={receipt:doc.date+' '+doc.id,order:order?order.date+' '+order.id:'',warehouse:lookup(db,'warehouses',doc.warehouse),employee:lookup(db,'employees',doc.employee),partner:lookup(db,'partners',line.supplier||doc.partner),item:line.item,spec:item?.spec||'',vatPrice:C.money(amount.price*(1+Number(doc.vatRate??10)/100)),boxUnit:item?.boxUnit??'',unit:item?.unit??'',total:amount.total,memo:line.memo??'',group1:item?.group1Name??item?.group1??'',group2:item?.group2Name??item?.group2??'',group3:item?.group3Name??item?.group3??'',name:spec.flat?(item?.name||line.item):name,qty:amount.qty,price:amount.price,supply:amount.supply,tax:amount.tax,blank:'',dueDate:line.dueDate||doc.dueDate||''};return {line,amount,values:spec.lineKeys.map(key=>fields[key]??'')};});
   if(query&&!JSON.stringify([header,details.map(x=>x.values)]).toLowerCase().includes(query))continue;
   groups.push({document:doc,header,lines:details});
  }
  groups.sort((a,b)=>a.document.date.localeCompare(b.document.date)||a.document.id.localeCompare(b.document.id));
  if(mode==='summary')return sortResult(summarize(db,groups,axes,spec.title,axisDirections),fields,order);
  return sortResult({layout:spec.flat?'flat':'grouped',columns:[...spec.header],rows:spec.flat?groups.flatMap(g=>g.lines.map(l=>l.values)):undefined,rowRecords:spec.flat?groups.flatMap(g=>g.lines.map(l=>({document:g.document,line:l.line}))):undefined,title:spec.title,headerColumns:[...spec.header],lineColumns:[...spec.line],groups,summary:{documents:groups.length,lines:groups.reduce((n,g)=>n+g.lines.length,0),quantity:C.quantity(groups.reduce((n,g)=>n+g.lines.reduce((s,l)=>s+l.amount.qty,0),0)),supply:C.money(groups.reduce((n,g)=>n+g.lines.reduce((s,l)=>s+l.amount.supply,0),0)),tax:C.money(groups.reduce((n,g)=>n+g.lines.reduce((s,l)=>s+l.amount.tax,0),0))}},fields,order);
 }

function summarize(db,documents,axes,title,axisDirections){
  const currencies=new Set(documents.map(g=>g.document.currency||'KRW'));if(currencies.size>1)throw Error('서로 다른 통화는 함께 집계할 수 없습니다. 내·외자 또는 거래처 조건을 좁혀 주세요.');
  const groups=new Map(),summary={documents:documents.length,lines:0,quantity:0,supply:0,tax:0,total:0};
  for(const group of documents){const positions=axes.includes('라인별')?new Map(group.document.lines.map((line,i)=>[line,i+1])):null;for(const detail of group.lines){
   const doc=group.document,line=detail.line,position=positions?.get(line),axis=axes.map(x=>summaryAxisCode(db,doc,line,x,position)),key=JSON.stringify(axis);
   let row=groups.get(key);if(!row){row={axis,labels:axis.map((code,i)=>summaryAxisLabel(db,axes[i],code,doc,position)),quantity:0,supply:0,tax:0,total:0};groups.set(key,row);}
   row.quantity=C.quantity(row.quantity+detail.amount.qty);summary.quantity=C.quantity(summary.quantity+detail.amount.qty);summary.lines++;
   for(const k of ['supply','tax','total']){row[k]=C.money(row[k]+detail.amount[k]);summary[k]=C.money(summary[k]+detail.amount[k]);}
  }}
  const records=[...groups.values()].sort((a,b)=>{for(let i=0;i<axes.length;i++){const order=(summaryDimensions[axes[i]].identity?a.labels[i]:a.axis[i]).localeCompare(summaryDimensions[axes[i]].identity?b.labels[i]:b.axis[i],'ko',{numeric:true});if(order)return axisDirections[i]==='desc'?-order:order;}return JSON.stringify(a.axis).localeCompare(JSON.stringify(b.axis));});
  const columns=[...axes,'수량','공급가액','부가세','합계'];
  const currency=[...currencies][0]||'';return {layout:'summary',title:title+' 집계'+(currency?' · '+currency:''),columns,headerColumns:columns,lineColumns:columns,rows:records.map(r=>[...r.labels,r.quantity,r.supply,r.tax,r.total]),records,axes:[...axes],identityBasisLabel:axes.some(axis=>summaryDimensions[axis].identity)?'전표별·라인별은 REA 전표 번호와 현재 행 번호로 표시합니다.':'',groupBasisLabel:['품목','거래처','프로젝트'].filter(name=>axes.some(axis=>axis.startsWith(name+'그룹'))).map(name=>name+'그룹은 현재 '+name+' 등록정보 기준으로 집계합니다.').join(' '),axisDirections:[...axisDirections],axisOrderLabel:axes.map((axis,i)=>axis+' '+(axisDirections[i]==='desc'?'내림차순':'오름차순')).join(' / '),groups:documents,summary,currency};
 }
